import copy

SYSTEMS = ["llm_only", "tfidf_rag", "graph_rag"]


def _sanitize(case):
    return {"id": case["id"], "question": case["question"]}


def run_experiment(cases, split, generate):
    selected = [c for c in cases if c.get("split") == split]
    answers = []
    for case in selected:
        sanitized = _sanitize(case)
        for system in SYSTEMS:
            answer = generate(copy.deepcopy(sanitized), system)
            answers.append({"id": case["id"], "system": system, "answer": answer})
    return {
        "manifest": {
            "split": split,
            "systems": list(SYSTEMS),
            "case_ids": [c["id"] for c in selected],
            "count": len(answers),
        },
        "answers": answers,
    }

import hashlib

SYSTEMS = ["llm_only", "tfidf_rag", "graph_rag"]


def _sha256(text):
    if not isinstance(text, str):
        text = "" if text is None else str(text)
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def score_answers(cases, answers, judge, apply_overrides=False):
    case_by_id = {}
    for case in cases:
        cid = case["id"]
        if cid in case_by_id:
            raise ValueError(f"duplicate case id: {cid!r}")
        case_by_id[cid] = case

    # Validate the answer matrix before any judging.
    seen = set()
    for answer in answers:
        if not isinstance(answer, dict):
            raise ValueError("answer entries must be mappings")
        for key in ("id", "system"):
            if key not in answer:
                raise ValueError(f"answer missing {key!r}: {answer!r}")
        cid = answer["id"]
        system = answer["system"]
        if cid not in case_by_id:
            raise ValueError(f"unknown case id in answers: {cid!r}")
        if system not in SYSTEMS:
            raise ValueError(f"unknown system: {system!r}")
        key = (cid, system)
        if key in seen:
            raise ValueError(f"duplicate answer for {key!r}")
        seen.add(key)

    expected = {(cid, system) for cid in case_by_id for system in SYSTEMS}
    missing = expected - seen
    if missing:
        raise ValueError(f"missing answers: {sorted(missing)!r}")

    rows = []
    for case in cases:
        cid = case["id"]
        for system in SYSTEMS:
            answer = next(
                a for a in answers if a["id"] == cid and a["system"] == system
            )
            score = judge(case, answer)
            score = dict(score) if score else {}
            if apply_overrides:
                override = case.get("legacy_override")
                if isinstance(override, dict):
                    stored = override.get("answer_sha256")
                    if stored is not None and stored == _sha256(answer.get("answer")):
                        for k, v in override.items():
                            if k == "answer_sha256":
                                continue
                            score[k] = v
            row = {**answer, **score, "adjudication": "scored"}
            if "total" not in row:
                row["total"] = score.get("total", 0)
            rows.append(row)
    return rows
